  const fmtBytes=n=>{if(!n)return '—';const u=['B','KB','MB','GB'];let i=0,v=Number(n);while(v>=1024&&i<u.length-1){v/=1024;i++}return `${v<10&&i?v.toFixed(1):Math.round(v)} ${u[i]}`};
