  const topLevelSubs=categoryId=>{const all=state.subcategories.filter(s=>s.status!=='paused'&&s.category_id===categoryId).sort((a,b)=>(a.sort_order||0)-(b.sort_order||0)||a.name.localeCompare(b.name,'pt-BR'));const childIds=new Set(state.subcategoryLinks.map(l=>l.child_subcategory_id));const top=all.filter(s=>!childIds.has(s.id));return top.length?top:all};
