    const monthly=settingNum('pro_monthly_price',19.9),semTotal=settingNum('pro_semester_total',59.4),semEq=settingNum('pro_semester_monthly_equiv',9.9),regular=monthly*6,saving=Math.max(0,regular-semTotal),pct=regular?Math.round(saving/regular*100):0;
