    const locked=tier==='semester'||tier==='admin';btn.hidden=locked;existing.hidden=!locked;if(locked){existing.textContent=tier==='admin'?'Sua conta administrativa já possui acesso integral.':'Seu PRO semestral já está ativo. Não é necessário comprar novamente.';return}
    existing.hidden=true;btn.href=`/checkout/?plan=${sem?'semester':'monthly'}`;btn.textContent=tier==='monthly'?'UPGRADE PARA SEMESTRAL →':'QUERO SER PRO →';$('#upgradeModalHeading').textContent=tier==='monthly'?'UPGRADE PARA SEMESTRAL':'ESCOLHA SEU PRO';
